// State Management for School Bus Rapid Replanning & Responsible AI System
import { BUSES, ROUTES, STUDENTS, DISRUPTIONS, OPERATIONS_METRICS, DRIVERS, SCHOOLS, DEPOT } from '../data/mockData.js';
import { replanningEngine, computeRouteProgress } from '../utils/replanningEngine.js';

function getDistanceMiles(coord1, coord2) {
  if (!coord1 || !coord2) return 0;
  const [lat1, lon1] = coord1;
  const [lat2, lon2] = coord2;
  const dy = (lat2 - lat1) * 69;
  const dx = (lon2 - lon1) * 55;
  return Math.sqrt(dx * dx + dy * dy);
}

class AppStore {
  constructor() {
    // Load pending offline changes from localStorage if any
    const savedPending = this.loadPendingOfflineChanges();

    this.state = {
      // Navigation & Flow State
      activeScreen: 'auth', // 'auth' -> 'role_selection' -> 'app'
      currentUser: null,
      currentRole: null, // 'dispatcher' | 'operations_manager'
      activeTab: 'dashboard', // 'dashboard', 'buses', 'routes', 'students', 'disruptions', 'replanning', 'reports', 'settings'

      // Network & System Resilience State
      networkStatus: 'online', // 'online' | 'degraded' | 'offline'
      pendingOfflineChanges: savedPending,
      lastSyncTimestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),

      // Domain Entities (Deep cloned for state isolation)
      buses: JSON.parse(JSON.stringify(BUSES)),
      routes: JSON.parse(JSON.stringify(ROUTES)),
      students: JSON.parse(JSON.stringify(STUDENTS)),
      disruptions: JSON.parse(JSON.stringify(DISRUPTIONS)),
      drivers: JSON.parse(JSON.stringify(DRIVERS)),
      schools: JSON.parse(JSON.stringify(SCHOOLS)),
      depot: JSON.parse(JSON.stringify(DEPOT)),
      metrics: JSON.parse(JSON.stringify(OPERATIONS_METRICS)),

      // Interaction State
      selectedBusId: null,
      selectedRouteId: null,
      selectedDisruptionId: "DIS-2026-001", // Default active critical disruption
      searchQuery: "",
      filterStatus: "all",

      // Modals
      activeModal: null, // 'create_disruption' | 'add_student' | 'bus_detail' | 'manual_location' | null
      modalPayload: null,

      // Toast notifications
      toasts: []
    };

    this.listeners = new Set();

    // Initialize Current Route Progress across all routes
    this.refreshAllRouteProgress();

    // Hook browser online / offline network events
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
      window.addEventListener('online', () => {
        this.setNetworkStatus('online');
      });
      window.addEventListener('offline', () => {
        this.setNetworkStatus('offline');
      });
    }
  }

  refreshAllRouteProgress() {
    if (!this.state || !this.state.routes) return;
    this.state.routes.forEach(route => {
      const bus = this.state.buses ? this.state.buses.find(b => b.id === route.assignedBus || b.routeId === route.id) : null;
      const progress = computeRouteProgress(route, bus);
      route.completedStops = progress.completedStops;
      route.currentStop = progress.currentStop;
      route.nextStop = progress.nextStop;
      route.remainingStops = progress.remainingStops;
      route.currentBusPosition = progress.currentBusPosition;
      route.routeProgressPercentage = progress.routeProgressPercentage;
    });
  }

  getRouteProgress(routeId) {
    const route = this.state.routes.find(r => r.id === routeId);
    if (!route) return null;
    const bus = this.state.buses.find(b => b.id === route.assignedBus || b.routeId === route.id);
    return computeRouteProgress(route, bus);
  }

  updateDriverLocation(driverId, coords, source = 'mobile_gps') {
    const driver = this.state.drivers.find(d => d.id === driverId || d.driverId === driverId);
    if (!driver) return null;
    driver.currentLocation = coords;
    driver.locationSource = source;
    driver.lastUpdated = new Date().toISOString();
    driver.isLocationStale = source === 'last_known';
    this.notify();
    return driver;
  }

  markDriverLocationStale(driverId) {
    const driver = this.state.drivers.find(d => d.id === driverId || d.driverId === driverId);
    if (!driver) return null;
    driver.isLocationStale = true;
    driver.locationSource = 'last_known';
    this.notify();
    return driver;
  }

