args.CodeContent:
/**
 * Insertion Position Consistency Tests
 *
 * Verifies that the greedy algorithm's chosen insertionPosition is:
 *   1. Stored in the disruption recommendation at generation time.
 *   2. Applied exactly at dispatcher acceptance time.
 *   3. Protected against stale routes via routeVersionKey fingerprinting.
 *   4. Never placed in already-completed stops.
 *   5. Reflected consistently in both the displayed recommendation and the final route.
 *   6. Recorded in the audit log with bus ID and insertion position.
 */

import { routeInsertion, replanningEngine, computeRouteProgress } from '../src/utils/replanningEngine.js';
import { AppStore } from '../src/state/store.js';

console.log('========================================================================');
console.log('  INSERTION POSITION CONSISTENCY: TEST SUITE');
console.log('========================================================================\n');

let passedTests = 0;
let totalTests = 0;

function assert(condition, testName, message = '') {
  totalTests++;
  if (condition) {
    passedTests++;
    console.log(`✅ [PASS] ${testName}`);
  } else {
    console.error(`❌ [FAIL] ${testName}${message ? ': ' + message : ''}`);
  }
}

// ─────────────────────────────────────────────────────────────
// SHARED ROUTE FIXTURE
// A 6-stop route where stops 0-1 are completed and 2-5 are pending.
// Valid greedy insertion range: positions 2 .. 6
// ─────────────────────────────────────────────────────────────
function makeRoute(overrides = {}) {
  return {
    id: 'RT-TEST',
    schoolId: 'SCH-01',
    assignedBus: 'BUS-TEST',
    assignedDriver: 'Test Driver',
    stops: [
      { id: 'S0', name: 'Depot Start',     status: 'completed', coords: [37.76, -122.45] },
      { id: 'S1', name: 'Oak Street',      status: 'completed', coords: [37.77, -122.44] },
      { id: 'S2', name: 'Pine Avenue',     status: 'next',      coords: [37.78, -122.43] },
      { id: 'S3', name: 'Elm Boulevard',   status: 'pending',   coords: [37.79, -122.42] },
      { id: 'S4', name: 'Maple Drive',     status: 'pending',   coords: [37.80, -122.41] },
      { id: 'S5', name: 'School Entrance', status: 'destination', coords: [37.81, -122.40] }
    ],
    totalStops: 6,
    ...overrides
  };
}

function makeBus(overrides = {}) {
  return {
    id: 'BUS-TEST',
    capacity: 54,
    currentLoad: 20,
    status: 'in_transit',
    routeId: 'RT-TEST',
    driverId: 'DRV-TEST',
    amenities: ['Wheelchair Lift'],
    coords: [37.78, -122.43],
    ...overrides
  };
}

function makeDriver(overrides = {}) {
  return {
    id: 'DRV-TEST',
    name: 'Test Driver',
    status: 'active',
    currentLocation: [37.78, -122.43],
    ...overrides
  };
}

// ─────────────────────────────────────────────────────────────
// TEST 1: Greedy selects position 2 → accepted route uses position 2
// ─────────────────────────────────────────────────────────────
{
  const route = makeRoute();
  const bus   = makeBus();

  // Put student pickup stop close to Stop 2 — should be inserted right after completed stops
  const studentStop = { name: 'Close to Pine Ave', coords: [37.775, -122.435], specialNeeds: 'None' };
  const result = routeInsertion.evaluateUrgentStudentInsertion(bus, route, studentStop);

  // Completed = 2, so valid positions are 2..6.  The closest stop is index 2.
  assert(
    result.bestPosition >= 2,
    '1. Greedy selects a valid insertion position (>= completed count)',
    `bestPosition=${result.bestPosition} — must be >= 2 (completed stops count)`
  );

  // Verify the returned newStops array respects the position
  assert(
    result.newStops[result.bestPosition]?.name === studentStop.name,
    '1b. newStops[bestPosition] is the inserted student stop',
    `Stop at position ${result.bestPosition}: ${result.newStops[result.bestPosition]?.name}`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 2: Greedy selects position 4 → accepted route uses position 4
// ─────────────────────────────────────────────────────────────
{
  const route = makeRoute();
  const bus   = makeBus();

  // Student pickup closer to Maple Drive (index 4) — best position should be 4 or 5
  const studentStop = { name: 'Near Maple Drive', coords: [37.795, -122.415], specialNeeds: 'None' };
  const result = routeInsertion.evaluateUrgentStudentInsertion(bus, route, studentStop);

  // The greedy algorithm tries all positions 2..6 and picks minimum added distance.
  // Maple Drive is stop 4, so best position should be 4 or 5.
  assert(
    result.bestPosition >= 2 && result.bestPosition <= 6,
    '2. Greedy selects position in valid range [2, 6] for far pickup',
    `bestPosition=${result.bestPosition}`
  );
  assert(
    result.newStops.length === route.stops.length + 1,
    '2b. newStops has exactly one additional stop',
    `Expected ${route.stops.length + 1}, got ${result.newStops.length}`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 3: First and last valid insertion positions
// ─────────────────────────────────────────────────────────────
{
  const route = makeRoute();
  const bus   = makeBus();

  // Student at very start of remaining route (position 2)
  const nearStart = { name: 'Near Pine Ave', coords: [37.780, -122.430], specialNeeds: 'None' };
  const startResult = routeInsertion.evaluateUrgentStudentInsertion(bus, route, nearStart);
  assert(
    startResult.bestPosition >= 2,
    '3a. First valid insertion position is >= 2 (no insertion into completed stops)',
    `bestPosition=${startResult.bestPosition}`
  );

  // Student at very end of route (position 6)
  const nearEnd = { name: 'Near School Entrance', coords: [37.810, -122.400], specialNeeds: 'None' };
  const endResult = routeInsertion.evaluateUrgentStudentInsertion(bus, route, nearEnd);
  assert(
    endResult.bestPosition <= route.stops.length,
    '3b. Last valid insertion position <= stops.length (append at end)',
    `bestPosition=${endResult.bestPosition}`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 4: Completed stops CANNOT be modified
// ─────────────────────────────────────────────────────────────
{
  const route = makeRoute();
  const bus   = makeBus();

  const studentStop = { name: 'Any Stop', coords: [37.77, -122.43], specialNeeds: 'None' };
  const result = routeInsertion.evaluateUrgentStudentInsertion(bus, route, studentStop);

  // Completed stops are at indices 0 and 1
  assert(
    result.bestPosition >= 2,
    '4. Insertion position never lands in completed stops (position < 2 would be a completed stop)',
    `bestPosition=${result.bestPosition}, completedCount=2`
  );

  // Double-check: stops 0 and 1 should remain 'completed' in newStops
  assert(
    result.newStops[0]?.status === 'completed' && result.newStops[1]?.status === 'completed',
    '4b. Completed stops remain unmodified in newStops',
    `stop[0].status=${result.newStops[0]?.status}, stop[1].status=${result.newStops[1]?.status}`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 5: Route changes after recommendation → stale recommendation detected
// ─────────────────────────────────────────────────────────────
{
  // Simulate the store's computeRouteVersionKey behaviour inline
  function computeRouteVersionKey(route) {
    if (!route || !route.stops) return 'no-route';
    const completedCount = route.stops.filter(s => s.status === 'completed' || s.status === 'passed').length;
    const firstName = route.stops[0]?.name || '';
    return `${route.id}:stops=${route.stops.length}:completed=${completedCount}:first=${firstName}`;
  }

  const routeAtRecommendationTime = makeRoute();
  const versionAtRec = computeRouteVersionKey(routeAtRecommendationTime);

  // Simulate route change: one more stop completes (bus progresses)
  const routeAfterProgress = makeRoute();
  routeAfterProgress.stops[2].status = 'completed'; // Pine Avenue now completed
  const versionAfterProgress = computeRouteVersionKey(routeAfterProgress);

  assert(
    versionAtRec !== versionAfterProgress,
    '5a. Route version key changes when a stop is marked completed (stale detection works)',
    `Before: "${versionAtRec}" | After: "${versionAfterProgress}"`
  );

  // Simulate route change: a new stop is added by another dispatcher action
  const routeWithExtraStop = makeRoute();
  routeWithExtraStop.stops.push({ id: 'S6', name: 'Extra Stop', status: 'pending', coords: [37.82, -122.39] });
  const versionWithExtra = computeRouteVersionKey(routeWithExtraStop);

  assert(
    versionAtRec !== versionWithExtra,
    '5b. Route version key changes when a stop is appended (stale detection works)',
    `Before: "${versionAtRec}" | After: "${versionWithExtra}"`
  );

  // Same route — should produce the same key (no false positives)
  const sameRoute = makeRoute();
  const samVersion = computeRouteVersionKey(sameRoute);
  assert(
    versionAtRec === samVersion,
    '5c. Route version key is stable for unchanged route (no false positives)',
    `"${versionAtRec}" should equal "${samVersion}"`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 6: Accepted plan and displayed recommendation contain the same route
// ─────────────────────────────────────────────────────────────
{
  const bus    = makeBus();
  const route  = makeRoute();
  const driver = makeDriver();

  const engineResult = replanningEngine.replan({
    type: 'urgent_add',
    studentStop: { name: 'New Stop', coords: [37.785, -122.425], specialNeeds: 'None' },
    destinationSchoolId: 'SCH-01',
    requiredSeats: 1
  }, { buses: [bus], routes: [route], drivers: [driver] });

  assert(
    !engineResult.noFeasibleSolution,
    '6a. Engine finds a feasible solution for the standard fixture',
    `noFeasibleSolution=${engineResult.noFeasibleSolution}`
  );

  // The engine's newRoute must have one more stop than the original
  assert(
    engineResult.newRoute !== null &&
    engineResult.newRoute.stops.length === route.stops.length + 1,
    '6b. Engine newRoute has exactly one additional stop',
    `newRoute.stops.length=${engineResult.newRoute?.stops.length}, original=${route.stops.length}`
  );

  // The insertion position stored in the result must agree with the newRoute
  const pos = engineResult.insertionPosition;
  assert(
    pos != null && engineResult.newRoute.stops[pos] !== undefined,
    '6c. engineResult.insertionPosition points to a valid stop in newRoute',
    `insertionPosition=${pos}, newRoute.stops.length=${engineResult.newRoute?.stops.length}`
  );
}

// ─────────────────────────────────────────────────────────────
// TEST 7: Final route metrics match the accepted plan
// ─────────────────────────────────────────────────────────────
{
  const bus    = makeBus();
  const route  = makeRoute();
  const driver = makeDriver();

  const engineResult = replanningEngine.replan({
    type: 'urgent_add',
    studentStop: { name: 'Metric Test Stop', coords: [37.785, -122.425], specialNeeds: 'None' },
    destinationSchoolId: 'SCH-01',
    requiredSeats: 1
  }, { buses: [bus], routes: [route], drivers: [driver] });

  if (!engineResult.noFeasibleSolution && engineResult.newRoute) {
    // totalStops must equal stops.length
    assert(
      engineResult.newRoute.totalStops === engineResult.newRoute.stops.length,
      '7a. newRoute.totalStops matches actual stops.length after insertion',
      `totalStops=${engineResult.newRoute.totalStops}, actual=${engineResult.newRoute.stops.length}`
    );

    // additionalDelay must be positive
    assert(
      engineResult.additionalDelay > 0,
      '7b. additionalDelay is positive (insertion adds some delay)',
      `additionalDelay=${engineResult.additionalDelay}`
    );

    // additionalDistance must be non-negative
    assert(
      engineResult.additionalDistance >= 0,
      '7c. additionalDistance is non-negative',
      `additionalDistance=${engineResult.additionalDistance}`
    );

    // routeProgress on newRoute: completedStops count should not exceed original completed count
    const originalCompletedCount = route.stops.filter(s => s.status === 'completed' || s.status === 'passed').length;
    const newCompletedCount = engineResult.newRoute.completedStops?.length ?? 0;
    assert(
      newCompletedCount === originalCompletedCount,
      '7d. Completed stops count unchanged after insertion (no retroactive completion)',
      `original completedCount=${originalCompletedCount}, newRoute completedCount=${newCompletedCount}`
    );
  } else {
    assert(false, '7. Engine should find a feasible solution for metrics test', `noFeasibleSolution=${engineResult.noFeasibleSolution}`);
  }
}

// ─────────────────────────────────────────────────────────────
// TEST 8: Audit log records selected bus and insertion position
// ─────────────────────────────────────────────────────────────
{
  // We test the audit-log contract by verifying that the AppStore's acceptAIPlan
  // creates a RECOMMENDATION_ACCEPTED audit event carrying both the bus ID and
  // the applied insertion position.

  const store = new AppStore();

  // Inject a minimal pre-built urgent_add disruption with a stored greedyInsertionPosition
  const busId   = 'BUS-05';  // in_depot standby bus — exists in mockData
  const routeId = 'RT-104';  // route in mockData
  const studentId = 'STU-AUDIT-TEST';

  // Add a test student
  store.state.students.unshift({
    id: studentId,
    name: 'Audit Test Student',
    status: 'urgent_added',
    busId: 'UNASSIGNED',
    routeId: 'UNASSIGNED',
    stopName: 'Audit Test Stop',
    schoolId: 'SCH-01',
    specialNeeds: 'None',
    pickupCoords: [37.77, -122.42]
  });

  const targetRoute = store.state.routes.find(r => r.id === routeId) || store.state.routes[0];
  const targetBus   = store.state.buses.find(b => b.id === busId) || store.state.buses[0];

  if (!targetRoute || !targetBus) {
    assert(false, '8. Pre-condition: target route and bus must exist in store mock data',
      `route=${!!targetRoute}, bus=${!!targetBus}`);
  } else {
    // Compute version key inline (mirrors store's private function)
    function computeRouteVersionKey(route) {
      if (!route || !route.stops) return 'no-route';
      const completedCount = route.stops.filter(s => s.status === 'completed' || s.status === 'passed').length;
      const firstName = route.stops[0]?.name || '';
      return `${route.id}:stops=${route.stops.length}:completed=${completedCount}:first=${firstName}`;
    }

    const versionKey = computeRouteVersionKey(targetRoute);

    const disruptionId = 'DIS-AUDIT-001';
    store.state.disruptions.unshift({
      id: disruptionId,
      _createdAtMs: Date.now() - 5000,
      type: 'urgent_add',
      title: 'Audit Test Disruption',
      studentId,
      status: 'unresolved',
      aiRecommendationAvailable: true,
      aiRecommendation: {
        planId: 'REPLAN-AUDIT-001',
        recommendedBusId: targetBus.id,
        recommendedRouteId: targetRoute.id,
        greedyInsertionPosition: 2,      // ← exact greedy position
        routeVersionKey: versionKey,      // ← matching version (not stale)
        urgentStopName: 'Audit Test Stop',
        urgentStopCoords: [37.77, -122.42],
        urgentStudentId: studentId,
        additionalDelayMins: 3.5
      }
    });

    const auditLengthBefore = store.state.auditEvents.length;
    store.acceptAIPlan(disruptionId);
    const auditLengthAfter = store.state.auditEvents.length;

    assert(
      auditLengthAfter > auditLengthBefore,
      '8a. acceptAIPlan creates at least one audit event',
      `before=${auditLengthBefore}, after=${auditLengthAfter}`
    );

    // The most recent audit event should record RECOMMENDATION_ACCEPTED
    // with the selected bus ID and applied insertion position
    const latestAuditEvent = store.state.auditEvents.find(
      e => e.action === 'RECOMMENDATION_ACCEPTED' && e.disruptionId === disruptionId
    );

    assert(
      latestAuditEvent != null,
      '8b. Audit log contains a RECOMMENDATION_ACCEPTED event for the disruption',
      `events: ${store.state.auditEvents.map(e => e.action).join(', ')}`
    );

    if (latestAuditEvent) {
      assert(
        latestAuditEvent.selectedPlan?.recommendedBusId === targetBus.id ||
        latestAuditEvent.selectedPlan?.appliedInsertionPosition != null,
        '8c. Audit event selectedPlan records the bus ID and/or applied insertion position',
        `selectedPlan=${JSON.stringify(latestAuditEvent.selectedPlan)}`
      );

      assert(
        latestAuditEvent.selectedPlan?.appliedInsertionPosition >= 0,
        '8d. Audit event records a valid appliedInsertionPosition (>= 0)',
        `appliedInsertionPosition=${latestAuditEvent.selectedPlan?.appliedInsertionPosition}`
      );
    }
  }
}

console.log('\n------------------------------------------------------------------------');
console.log(`Insertion Position Consistency Tests: ${passedTests}/${totalTests} Passed (${((passedTests / totalTests) * 100).toFixed(0)}%).`);
console.log('------------------------------------------------------------------------\n');

if (passedTests !== totalTests) {
  process.exit(1);
}

