retryFailedActions() {
  const failedItems = this.state.pendingOfflineChanges.filter(a => a.status === 'FAILED');
  if (failedItems.length === 0) {
    this.showToast('No failed actions to retry.', 'info');
    return { success: true, count: 0, syncedCount: 0, failedCount: 0 };
  }

  failedItems.forEach(action => {
    action.status = 'PENDING';
    action.error = null;
    action.errorMessage = null;
  });

  this.showToast(`Retrying ${failedItems.length} failed action(s)...`, 'info');
  return this.syncPendingOfflineChanges();
}

